216	
217	    /** The flat amounts asked to be taken off the subtotal, added up; zero when there is no flat discount. */
218	    public BigDecimal getDiscountAmount() {
219	        return discounts.stream().map(InvoiceDiscount::getDiscountAmount).reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
220	    }
221	
222	    /**
223	     * How much one of this invoice's discounts actually takes off the subtotal, to the cent. The
224	     * percentages are taken first, each its share of the subtotal (never more than its cap, if it has
225	     * one), then the flat amounts in the order they were added; none takes off more than is left after
226	     * those before it.
227	     */
228	    public BigDecimal discountTakenBy(InvoiceDiscount discount) {
229	        BigDecimal subtotal = getSubtotal();
230	        BigDecimal left = subtotal;
231	        for (InvoiceDiscount d : discountsInOrderTaken()) {
232	            BigDecimal wanted = d.isPercentage() ? percentWanted(subtotal, d) : d.getDiscountAmount();
233	            BigDecimal taken = wanted.min(left.max(BigDecimal.ZERO.setScale(2)));
234	            if (d == discount) {
235	                return taken;
236	            }
237	            left = left.subtract(taken);
238	        }
239	        return BigDecimal.ZERO.setScale(2);
240	    }
241	
242	    /** What a percentage discount asks to take off the subtotal: its share, never more than its cap. */
243	    private static BigDecimal percentWanted(BigDecimal subtotal, InvoiceDiscount discount) {
244	        BigDecimal share = percentOf(subtotal, discount.getDiscountPct());
245	        return isCappedAt(subtotal, discount) ? share.min(discount.getDiscountCap()) : share;
246	    }
247	
248	    /** Whether a discount's cap limits what it takes off the given subtotal. */
249	    private static boolean isCappedAt(BigDecimal subtotal, InvoiceDiscount discount) {
250	        return discount.getDiscountCap() != null
251	                && percentOf(subtotal, discount.getDiscountPct()).compareTo(discount.getDiscountCap()) > 0;
252	    }
253	
254	    /** The percentage discounts first, then the flat ones, each in the order they were added. */
255	    private List<InvoiceDiscount> discountsInOrderTaken() {
256	        List<InvoiceDiscount> ordered = new ArrayList<>(discounts.stream().filter(InvoiceDiscount::isPercentage).toList());
257	        ordered.addAll(discounts.stream().filter(d -> !d.isPercentage()).toList());
258	        return ordered;
259	    }
260	
261	    /**
262	     * What the line items add up to, before the invoice's discount: the sum of each line after its own
263	     * discount, rounded to the cent.
264	     */
265	    public BigDecimal getSubtotal() {
266	        return lineItems.stream().map(InvoiceLineItem::getAmount).reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
267	    }
268	
269	    /** How much the discounts take off the subtotal together (what each takes off, added up), to the cent. */
270	    public BigDecimal getDiscount() {
271	        return discounts.stream().map(this::discountTakenBy).reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
272	    }
273	
274	    /**
275	     * How much the client saves on this invoice: every discount added together, both what the lines take
276	     * off themselves and what the invoice's discounts take off the subtotal, to the cent.
277	     */
278	    public BigDecimal getTotalSavings() {
279	        BigDecimal lineSavings = lineItems.stream().map(l -> l.getGrossAmount().subtract(l.getAmount()))
280	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
281	        return lineSavings.add(getDiscount());
282	    }
283	
284	    /** The sales tax percentage added after the discount; zero when there is no tax. */
285	    public BigDecimal getTaxPct() {
286	        return taxPct;
287	    }
288	
289	    /** Whether the prices already include the tax, so it is worked back out rather than added on. */
290	    public boolean isTaxInclusive() {
291	        return taxInclusive;
292	    }
293	
294	    /** Whether the invoice is for a tax-exempt client, so none of its lines are taxed. */
295	    public boolean isTaxExempt() {
296	        return taxExempt;
297	    }
298	
299	    /**
300	     * What the sales tax is charged on: the taxable lines (leaving out tax-free ones) less the discount
301	     * taken off them, to the cent. On a tax-inclusive invoice that is what is left of them once the tax
302	     * inside them is taken out.
303	     */
304	    public BigDecimal getTaxableBase() {
305	        BigDecimal gross = getDiscountedTaxable();
306	        return taxInclusive ? gross.subtract(getTax()) : gross;
307	    }
308	
309	    /**
310	     * How much sales tax is added on the taxable base (or is inside it, when tax-inclusive): the tax on
311	     * each taxable line rounded to the cent, added up.
312	     */
313	    public BigDecimal getTax() {
314	        return sumOverTaxableLines(this::taxOn);
315	    }
316	
317	    /** The flat amount (such as a handling fee) added to the total after tax; zero when there is none. */
318	    public BigDecimal getSurcharge() {
319	        return surcharge;
320	    }
321	
322	    /** The least this invoice bills; zero when there is no minimum charge. */
323	    public BigDecimal getMinimumCharge() {
324	        return minimumCharge;
325	    }
326	
327	    /**
328	     * What the invoice comes to before any minimum charge: the subtotal less the discount plus the tax
329	     * (unless it is inside the prices), plus the surcharge.
330	     */
331	    public BigDecimal getNetTotal() {
332	        BigDecimal discounted = getSubtotal().subtract(getDiscount());
333	        return (taxInclusive ? discounted : discounted.add(getTax())).add(surcharge);
334	    }
335	
336	    /** Whether the net total came out under the minimum charge, so the minimum is billed instead. */
337	    public boolean isMinimumApplied() {
338	        return getNetTotal().compareTo(minimumCharge) < 0;
339	    }
340	
341	    /** The taxable lines (leaving out tax-free ones), each less the discount taken off it, added up. */
342	    private BigDecimal getDiscountedTaxable() {
343	        return sumOverTaxableLines(line -> line);
344	    }
345	
346	    /**
347	     * Works a figure out on each taxable line after its discount, to the cent, and adds them up. A
348	     * tax-exempt invoice has no taxable lines.
349	     */
350	    private BigDecimal sumOverTaxableLines(UnaryOperator<BigDecimal> perLine) {
351	        return lineItems.stream().filter(l -> !taxExempt && !l.isTaxExempt()).map(InvoiceLineItem::getAmount)
352	                .map(amount -> perLine.apply(amount.subtract(discountOn(amount))))
353	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
354	    }
355	
356	    /**
357	     * The part of a tax-inclusive price that is the given percentage, worked back out of it: the price
358	     * divided in proportion to the sales tax rate it includes (e.g. 20% tax in 120 is 20).
359	     */
360	    private BigDecimal includedIn(BigDecimal price, BigDecimal pct) {
361	        BigDecimal grossPct = BigDecimal.valueOf(100).add(taxPct);
362	        return price.multiply(pct).divide(grossPct, 2, RoundingMode.HALF_UP);
363	    }
364	
365	    /** The percentage taken off what is owed when paid early; zero when none is offered. */
366	    public BigDecimal getEarlyPaymentPct() {
367	        return earlyPaymentPct;
368	    }
369	
370	    /**
371	     * How many days after being issued the invoice must be paid within to get the early-payment discount:
372	     * the early-payment window in its client's payment terms; zero when the client has none.
373	     */
374	    public int getEarlyPaymentDays() {
375	        Integer window = project.getClient().getEarlyPaymentWindowDays();
376	        return window != null ? window : 0;
377	    }
378	
379	    /** Whether an early-payment discount is offered: a percentage off when paid within the client's early-payment window. */
380	    public boolean offersEarlyPayment() {
381	        return earlyPaymentPct.signum() > 0 && getEarlyPaymentDays() > 0;
382	    }
383	
384	    /** The last day the invoice can be paid to get the early-payment discount; null when none is offered. */
385	    public LocalDate getEarlyPaymentBy() {
386	        return offersEarlyPayment() ? issuedDate.plusDays(getEarlyPaymentDays()) : null;
387	    }
388	
389	    /**
390	     * The reduced amount to pay when settling early: the amount less the early-payment percentage of it,
391	     * to the cent; null when no early-payment discount is offered.
392	     */
393	    public BigDecimal getEarlyPaymentAmount() {
394	        return offersEarlyPayment() ? amount.subtract(percentOf(amount, earlyPaymentPct)) : null;
395	    }
396	
397	    /** The percentage of the amount given back when paid before the due date; zero when none is offered. */
398	    public BigDecimal getRebatePct() {
399	        return rebatePct;
400	    }
401	
402	    /** The settlement rebate for paying before the due date: the rebate percentage of the amount, to the cent; null when none is offered. */
403	    public BigDecimal getRebate() {
404	        return rebatePct.signum() > 0 ? percentOf(amount, rebatePct) : null;
405	    }
406	
407	    /** The settlement rebate given back because the client paid early enough; zero when it has not been earned. */
408	    public BigDecimal getRebateTaken() {
409	        return rebateTaken;
410	    }
411	
412	    /** Whether the settlement rebate has been earned, so the invoice settles for the reduced amount. */
413	    public boolean isRebateTaken() {
414	        return rebateTaken.signum() > 0;
415	    }
416	
417	    /**
418	     * The reduced amount the client actually needed to pay once the rebate was earned: the amount less the rebate
419	     * given back; null when no rebate has been earned.
420	     */
421	    public BigDecimal getRebatedAmount() {
422	        return isRebateTaken() ? amount.subtract(rebateTaken) : null;
423	    }
424	
425	    /**
426	     * Gives back the settlement rebate when what was paid before the due date, together with the credit and any
427	     * part written off, has cleared the amount less the rebate. Once taken it stays taken.
428	     */
429	    public void takeRebateIfEarned(BigDecimal paidBeforeDue, BigDecimal credited) {
430	        BigDecimal rebate = getRebate();
431	        if (rebate == null || isRebateTaken() || dueDate == null) {
432	            return;
433	        }
434	        if (paidBeforeDue.add(credited).add(writeOffAmount).compareTo(amount.subtract(rebate)) >= 0) {
435	            this.rebateTaken = rebate;
436	        }
437	    }
438	
439	    public InvoiceStatus getStatus() {
440	        return status;
441	    }
442	
443	    public LocalDate getIssuedDate() {
444	        return issuedDate;
445	    }
446	
447	    public LocalDate getDueDate() {
448	        return dueDate;
449	    }
450	
451	    public List<InvoiceLineItem> getLineItems() {
452	        return List.copyOf(lineItems);
453	    }
454	
455	    /** Adds a line to this invoice and reworks its amount to include what the line charges. */
456	    public InvoiceLineItem addLineItem(String description, BigDecimal qty, String unit, BigDecimal unitPrice) {
457	        return addLineItem(description, qty, unit, unitPrice, false, BigDecimal.ZERO);
458	    }
459	
460	    /**
461	     * Adds a line, taxable or tax-free and with any discount of its own, to this invoice and reworks its
462	     * amount to include what the line charges after that discount.
463	     */
464	    public InvoiceLineItem addLineItem(String description, BigDecimal qty, String unit, BigDecimal unitPrice,
465	            boolean taxExempt, BigDecimal discountPct) {
466	        InvoiceLineItem item = new InvoiceLineItem(this, description, qty, unit, unitPrice, taxExempt, discountPct);
467	        lineItems.add(item);
468	        recalculateAmount();
469	        return item;
470	    }
471	
472	    /** Changes one of this invoice's lines and reworks its amount to match. */
473	    public void updateLineItem(InvoiceLineItem item, String description, BigDecimal qty, String unit,
474	            BigDecimal unitPrice, boolean taxExempt, BigDecimal discountPct) {
475	        item.update(description, qty, unit, unitPrice, taxExempt, discountPct);
476	        recalculateAmount();
477	    }
478	
479	    /** Removes a line from this invoice and reworks its amount to no longer include what the line charged. */
480	    public void removeLineItem(InvoiceLineItem item) {
481	        lineItems.remove(item);
482	        recalculateAmount();
483	    }
484	
485	    /** The line on this invoice with the given id, if there is one. */
486	    public Optional<InvoiceLineItem> findLineItem(Long lineItemId) {
487	        return lineItems.stream().filter(l -> l.getId().equals(lineItemId)).findFirst();
488	    }
489	
490	    /** Sets this invoice's one discount as a percentage and reworks its amount to match. */
491	    public void applyDiscount(BigDecimal discountPct) {
492	        applyDiscount(discountPct, BigDecimal.ZERO);
493	    }
494	
495	    /**
496	     * Sets this invoice's one discount, either a percentage or a flat amount (the other being zero; zero
497	     * for both leaves no discount), and reworks its amount to match.
498	     */
499	    public void applyDiscount(BigDecimal discountPct, BigDecimal discountAmount) {
500	        applyDiscount(discountPct, discountAmount, null);
501	    }
502	
503	    /**
504	     * Sets this invoice's one discount, either a percentage (optionally capped at the most it takes off) or
505	     * a flat amount, replacing any it had (zero for both leaves no discount), and reworks its amount to match.
506	     */
507	    public void applyDiscount(BigDecimal discountPct, BigDecimal discountAmount, BigDecimal discountCap) {
508	        InvoiceDiscount discount = new InvoiceDiscount(this, discountPct, discountAmount, discountCap);
509	        if (discountPct.signum() == 0 && discountAmount.signum() == 0) {
510	            discounts.clear();
511	        } else if (discounts.isEmpty()) {
512	            discounts.add(discount);
513	        } else {
514	            // The existing discount is changed in place, as an invoice only ever has the one.
515	            discounts.get(0).replaceWith(discount);
516	        }
517	        recalculateAmount();
518	    }
519	
520	    /** Sets the sales tax percentage added to this invoice and reworks its amount to match. */
521	    public void applyTax(BigDecimal taxPct) {
522	        this.taxPct = taxPct.setScale(2, RoundingMode.HALF_UP);
523	        recalculateAmount();
524	    }
525	
526	    /** Sets whether this invoice's prices already include tax and reworks its amount to match. */
527	    public void applyTaxInclusive(boolean taxInclusive) {
528	        this.taxInclusive = taxInclusive;
529	        recalculateAmount();
530	    }
531	
532	    /** Sets whether this invoice is for a tax-exempt client and reworks its amount to match. */
533	    public void applyTaxExempt(boolean taxExempt) {
534	        this.taxExempt = taxExempt;
535	        recalculateAmount();
536	    }
537	
538	    /** Sets the flat surcharge (such as a handling fee) added to this invoice and reworks its amount to match. */
539	    public void applySurcharge(BigDecimal surcharge) {
540	        this.surcharge = surcharge.setScale(2, RoundingMode.HALF_UP);
541	        recalculateAmount();
542	    }
543	
544	    /** Sets the minimum charge billed on this invoice and reworks its amount to match. */
545	    public void applyMinimumCharge(BigDecimal minimumCharge) {
546	        this.minimumCharge = minimumCharge.setScale(2, RoundingMode.HALF_UP);
547	        recalculateAmount();
548	    }
549	
550	    /** Sets the late fee charged for each day this invoice is overdue. It does not change the amount invoiced. */
551	    public void applyLateFee(BigDecimal lateFeePerDay) {
552	        this.lateFeePerDay = lateFeePerDay.setScale(2, RoundingMode.HALF_UP);
553	    }
554	
555	    public BigDecimal getLateFeePerDay() {
556	        return lateFeePerDay;
557	    }
558	
559	    /** Sets the interest charged for each day an instalment of this invoice is paid late. */
560	    public void applyInstalmentInterest(BigDecimal interestPerDay) {
561	        this.instalmentInterestPerDay = interestPerDay.setScale(2, RoundingMode.HALF_UP);
562	    }
563	
564	    public BigDecimal getInstalmentInterestPerDay() {
565	        return instalmentInterestPerDay;
566	    }
567	
568	    /** Sets the percentage of this invoice held back as retention. It does not change the amount invoiced. */
569	    public void applyRetention(BigDecimal retentionPct) {
570	        this.retentionPct = retentionPct.setScale(2, RoundingMode.HALF_UP);
571	    }
572	
573	    public BigDecimal getRetentionPct() {
574	        return retentionPct;
575	    }
576	
577	    /** Releases the retention held back, so it becomes due. The percentage is kept on record. */
578	    public void releaseRetention() {
579	        this.retentionReleased = true;
580	    }
581	
582	    public boolean isRetentionReleased() {
583	        return retentionReleased;
584	    }
585	
586	    /**
587	     * The amount held back as retention: the retention percentage of the amount invoiced, or nothing once
588	     * the retention has been released.
589	     */
590	    public BigDecimal getRetention() {
591	        return retentionReleased ? BigDecimal.ZERO.setScale(2) : percentOf(amount, retentionPct);
592	    }
593	
594	    /** What is due now: the amount invoiced less the retention held back. */
595	    public BigDecimal getDueNow() {
596	        return amount.subtract(getRetention());
597	    }
598	
599	    /**
600	     * How many days past its due date the invoice is on the given day; zero unless it has been sent and
601	     * is still owed (sent or part paid).
602	     */
603	    public long daysLate(InvoiceStatus status, LocalDate today) {
604	        if (status != InvoiceStatus.SENT && status != InvoiceStatus.PARTIAL) {
605	            return 0;
606	        }
607	        return Math.max(0, ChronoUnit.DAYS.between(dueDate, today));
608	    }
609	
610	    /** The late fee accrued by the given day: the fee per day times the days the invoice is overdue. */
611	    public BigDecimal lateFee(InvoiceStatus status, LocalDate today) {
612	        return lateFeePerDay.multiply(BigDecimal.valueOf(daysLate(status, today))).setScale(2, RoundingMode.HALF_UP);
613	    }
614	
615	    /**
616	     * Sets the early-payment discount offered on this invoice: the percentage taken off what is owed if it is
617	     * paid within its client's early-payment window. It does not change the amount owed.
618	     */
619	    public void applyEarlyPayment(BigDecimal earlyPaymentPct) {
620	        this.earlyPaymentPct = earlyPaymentPct.setScale(2, RoundingMode.HALF_UP);
621	    }
622	
623	    /**
624	     * Sets the settlement rebate offered on this invoice: the percentage of the amount given back if it is
625	     * paid before the due date. It does not change the amount invoiced.
626	     */
627	    public void applyRebate(BigDecimal rebatePct) {
628	        this.rebatePct = rebatePct.setScale(2, RoundingMode.HALF_UP);
629	    }
630	
631	    /**
632	     * The discount taken off one line, to the cent: the uncapped percentages together, plus its share of
633	     * what the flat amounts and the capped percentages take off in proportion to what the line charges
634	     * out of the subtotal.
635	     */
636	    private BigDecimal discountOn(BigDecimal line) {
637	        BigDecimal subtotal = getSubtotal();
638	        BigDecimal pct = percentOf(line, uncappedPct(subtotal));
639	        if (subtotal.signum() == 0) {
640	            return pct;
641	        }
642	        BigDecimal flatShare = sharedDiscount(subtotal).multiply(line).divide(subtotal, 2, RoundingMode.HALF_UP);
643	        return pct.add(flatShare);
644	    }
645	
646	    /** The percentages not limited by a cap, added up (never more than 100). */
647	    private BigDecimal uncappedPct(BigDecimal subtotal) {
648	        return discounts.stream().filter(d -> d.isPercentage() && !isCappedAt(subtotal, d)).map(InvoiceDiscount::getDiscountPct)
649	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add).min(BigDecimal.valueOf(100).setScale(2));
650	    }
651	
652	    /**
653	     * What the flat discounts and the capped percentages actually take off the subtotal together, shared
654	     * across the lines in proportion to what each charges.
655	     */
656	    private BigDecimal sharedDiscount(BigDecimal subtotal) {
657	        return discounts.stream().filter(d -> !d.isPercentage() || isCappedAt(subtotal, d)).map(this::discountTakenBy)
658	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
659	    }
660	
661	    /** The sales tax on one discounted taxable line (or inside it, when tax-inclusive), to the cent. */
662	    private BigDecimal taxOn(BigDecimal line) {
663	        return taxInclusive ? includedIn(line, taxPct) : percentOf(line, taxPct);
664	    }
665	
666	    private static BigDecimal percentOf(BigDecimal base, BigDecimal pct) {
667	        return base.multiply(pct).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_UP);
668	    }
669	
670	    private void recalculateAmount() {
671	        this.amount = getNetTotal().max(minimumCharge);
672	    }
673	
674	    /** Marks this invoice as sent to the client on the given day, keeping a snapshot of its total as sent. */
675	    public void markSent(LocalDate sentOn) {
676	        this.status = InvoiceStatus.SENT;
677	        this.sentSnapshotTotal = amount;
678	        this.sentSnapshotDate = sentOn;
679	    }
680	
681	    /** The invoice as it read when it was sent; empty until it is sent. */
682	    public Optional<InvoiceSnapshot> getSentSnapshot() {
683	        return sentSnapshotTotal == null ? Optional.empty()
684	                : Optional.of(new InvoiceSnapshot(sentSnapshotTotal, sentSnapshotDate));
685	    }
686	
687	    /** Cancels this invoice, so it is no longer owed. */
688	    public void markVoid() {
689	        this.status = InvoiceStatus.VOID;
690	    }
691	
692	    /** Flags this invoice as disputed by the client; it still counts as owed. */
693	    public void markDisputed() {
694	        this.disputed = true;
695	    }
696	
697	    public boolean isDisputed() {
698	        return disputed;
699	    }
700	
701	    /** Writes this invoice off as bad debt, so it is no longer owed. */
702	    public void markWrittenOff() {
703	        this.status = InvoiceStatus.WRITTEN_OFF;
704	    }
705	
706	    /** Writes part of this invoice off as bad debt, so that part is no longer owed while the rest still is. */
707	    public void writeOffPart(BigDecimal part) {
708	        this.writeOffAmount = writeOffAmount.add(part).setScale(2, RoundingMode.HALF_UP);
709	    }
710	
711	    public BigDecimal getWriteOffAmount() {
712	        return writeOffAmount;
713	    }
714	
715	    public String getPoNumber() {
716	        return poNumber;
717	    }
718	
719	    public void setPoNumber(String poNumber) {
720	        this.poNumber = poNumber;
721	    }
722	
723	    /**
724	     * What is left to pay on this invoice given the totals paid and credited against it, less any part written
725	     * off and any settlement rebate earned; nothing once it is void or written off.
726	     */
727	    public BigDecimal amountDue(BigDecimal paid, BigDecimal credited) {
728	        return status.isClosedUnpaid() ? BigDecimal.ZERO.setScale(2)
729	                : amount.subtract(paid).subtract(credited).subtract(writeOffAmount).subtract(rebateTaken);
730	    }
731	
732	    /**
733	     * What the client owes on this invoice right now given the totals paid and credited against it: what is
734	     * left to pay less the retention still held back, never below nothing on account of the retention.
735	     */
736	    public BigDecimal dueNow(BigDecimal paid, BigDecimal credited) {
737	        BigDecimal left = amountDue(paid, credited);
738	        if (left.signum() <= 0 || status.isClosedUnpaid()) {
739	            return left;
740	        }
741	        return left.subtract(getRetention()).max(BigDecimal.ZERO.setScale(2));
742	    }
743	
744	    /**
745	     * This invoice's status given the totals paid and credited against it. Once sent, it is PAID when the
746	     * payments, credit notes, any part written off and any settlement rebate earned together clear the amount, PARTIAL once something has been
747	     * paid, credited or written off, otherwise still SENT. Drafts, void and written-off invoices keep their status, as does one marked paid by hand.
748	     */
749	    public InvoiceStatus statusFor(BigDecimal paid, BigDecimal credited) {
750	        if (status == InvoiceStatus.DRAFT || status.isClosedUnpaid()) {
751	            return status;
752	        }
753	        BigDecimal settled = paid.add(credited).add(writeOffAmount).add(rebateTaken);
754	        if (settled.compareTo(amount) >= 0 || (status == InvoiceStatus.PAID && settled.signum() == 0)) {
755	            return InvoiceStatus.PAID;
756	        }
757	        return settled.signum() > 0 ? InvoiceStatus.PARTIAL : InvoiceStatus.SENT;
758	    }
759	
760	    /**
761	     * Works out this sent invoice's status from what is still owed on it after the totals paid and credited against
762	     * it and any part written off: PAID once nothing is left, PARTIAL once something has been settled, otherwise
763	     * still SENT.
764	     */
765	    public void applySettledTotals(BigDecimal paid, BigDecimal credited) {
766	        if (status == InvoiceStatus.DRAFT || status.isClosedUnpaid()) {
767	            throw new IllegalStateException("A " + status.name().toLowerCase() + " invoice cannot be settled");
768	        }
769	        this.status = statusFor(paid, credited);
770	    }
771	}
